-- ====================================================================================================
-- CAMPUS2CAREER COMPREHENSIVE SECURITY HARDENING & PRODUCTION CANDIDATES SEED SCRIPT
-- ====================================================================================================

-- ----------------------------------------------------------------------------------------------------
-- 1. ROW LEVEL SECURITY (RLS) LOCKDOWN
-- Prevents anon / client-side browser console scraping of sensitive OTPs and users
-- ----------------------------------------------------------------------------------------------------
ALTER TABLE public.password_resets ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.pending_verifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.login_attempts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.login_rate_limits ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;

-- Clean existing permissive policies
DROP POLICY IF EXISTS "Full access to password_resets" ON public.password_resets;
DROP POLICY IF EXISTS "Allow anon read password_resets" ON public.password_resets;
DROP POLICY IF EXISTS "Service role only access to password_resets" ON public.password_resets;

DROP POLICY IF EXISTS "Full access to pending_verifications" ON public.pending_verifications;
DROP POLICY IF EXISTS "Service role only access to pending_verifications" ON public.pending_verifications;

DROP POLICY IF EXISTS "Full access to login_attempts" ON public.login_attempts;
DROP POLICY IF EXISTS "Service role only access to login_attempts" ON public.login_attempts;

DROP POLICY IF EXISTS "Full access to login_rate_limits" ON public.login_rate_limits;
DROP POLICY IF EXISTS "Service role only access to login_rate_limits" ON public.login_rate_limits;

DROP POLICY IF EXISTS "Full access to users" ON public.users;
DROP POLICY IF EXISTS "Allow all users" ON public.users;
DROP POLICY IF EXISTS "Public read users" ON public.users;
DROP POLICY IF EXISTS "Service role full access on users" ON public.users;

-- Restrict backend access strictly to service_role
CREATE POLICY "Service role only access to password_resets"
ON public.password_resets FOR ALL TO service_role USING (true) WITH CHECK (true);

CREATE POLICY "Service role only access to pending_verifications"
ON public.pending_verifications FOR ALL TO service_role USING (true) WITH CHECK (true);

CREATE POLICY "Service role only access to login_attempts"
ON public.login_attempts FOR ALL TO service_role USING (true) WITH CHECK (true);

CREATE POLICY "Service role only access to login_rate_limits"
ON public.login_rate_limits FOR ALL TO service_role USING (true) WITH CHECK (true);

CREATE POLICY "Service role full access on users"
ON public.users FOR ALL TO service_role USING (true) WITH CHECK (true);

-- ----------------------------------------------------------------------------------------------------
-- 2. SCHEMA HARDENING (Eliminate Plaintext Password & Session Versioning)
-- ----------------------------------------------------------------------------------------------------
ALTER TABLE public.users DROP COLUMN IF EXISTS password;
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS token_version INT DEFAULT 1;
ALTER TABLE public.users ADD COLUMN IF NOT EXISTS updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE public.password_resets ADD COLUMN IF NOT EXISTS attempts INT DEFAULT 0;

-- Candidates Table Extensions
ALTER TABLE public.candidates ALTER COLUMN skills SET DEFAULT '{}'::text[];
ALTER TABLE public.candidates ALTER COLUMN skills DROP NOT NULL;
ALTER TABLE public.candidates ADD COLUMN IF NOT EXISTS capstone_proof TEXT;
ALTER TABLE public.candidates ADD COLUMN IF NOT EXISTS bio TEXT;
ALTER TABLE public.candidates ADD COLUMN IF NOT EXISTS verified_status VARCHAR(100) DEFAULT 'LIVE VERIFIED';
ALTER TABLE public.candidates ADD COLUMN IF NOT EXISTS status VARCHAR(100) DEFAULT 'LIVE VERIFIED';

-- Student Skill Progress Extensions
ALTER TABLE public.student_skill_progress ADD COLUMN IF NOT EXISTS skill_id VARCHAR(100);
ALTER TABLE public.student_skill_progress ADD COLUMN IF NOT EXISTS category VARCHAR(100) DEFAULT 'Core Skill';
ALTER TABLE public.student_skill_progress ADD COLUMN IF NOT EXISTS base_percentage INT DEFAULT 35;
ALTER TABLE public.student_skill_progress ADD COLUMN IF NOT EXISTS diagnostic_score INT DEFAULT 0;
ALTER TABLE public.student_skill_progress ADD COLUMN IF NOT EXISTS lecture_score INT DEFAULT 0;
ALTER TABLE public.student_skill_progress ADD COLUMN IF NOT EXISTS marathon_score INT DEFAULT 0;
ALTER TABLE public.student_skill_progress ADD COLUMN IF NOT EXISTS total_score INT DEFAULT 35;
ALTER TABLE public.student_skill_progress ADD COLUMN IF NOT EXISTS latest_exam_score NUMERIC(5,2) DEFAULT 0;
ALTER TABLE public.student_skill_progress ADD COLUMN IF NOT EXISTS status VARCHAR(100) DEFAULT 'UNVERIFIED BASELINE';
ALTER TABLE public.student_skill_progress ADD COLUMN IF NOT EXISTS verified BOOLEAN DEFAULT FALSE;
ALTER TABLE public.student_skill_progress ADD COLUMN IF NOT EXISTS lectures_completed INT DEFAULT 0;
ALTER TABLE public.student_skill_progress ADD COLUMN IF NOT EXISTS current_milestone TEXT;
ALTER TABLE public.student_skill_progress ADD COLUMN IF NOT EXISTS next_milestone TEXT;

-- ----------------------------------------------------------------------------------------------------
-- 3. AARAV PATEL (theyareop@gmail.com) 92.0% EXACT CALIBRATION
-- Skill percentages: SolidWorks (94%), FEA (92%), CFD (90%), CNC (92%), Failure Analysis (92%)
-- Average: (94 + 92 + 90 + 92 + 92) / 5 = 92.0%
-- ----------------------------------------------------------------------------------------------------
UPDATE users
SET dynamic_competence_percent = 92.0,
    avg_exam_score = 92.0,
    total_study_minutes = GREATEST(COALESCE(total_study_minutes, 0), 380),
    total_lecture_minutes = GREATEST(COALESCE(total_lecture_minutes, 0), 240),
    skills = ARRAY['SolidWorks & Parametric CAD', 'FEA Stress Analysis (ANSYS)', 'CFD Fluid & Thermal Flow', 'CNC Machining & DFM Guidelines', 'Failure Analysis & Reliability']
WHERE id = 'a0000000-0000-4000-8000-000000000003'::uuid OR LOWER(email) = 'theyareop@gmail.com';

UPDATE candidates
SET skill_score = 92,
    dynamic_competence_percent = 92.0,
    readiness_score = 92.0,
    verified_status = 'LIVE VERIFIED',
    status = 'LIVE VERIFIED',
    skills = ARRAY['SolidWorks & Parametric CAD', 'FEA Stress Analysis (ANSYS)', 'CFD Fluid & Thermal Flow', 'CNC Machining & DFM Guidelines', 'Failure Analysis & Reliability'],
    capstone_proof = 'Engineered multi-stage reduction gearbox with FEA-validated fatigue life exceeding 10^7 cycles and automated CNC G-code pipeline.'
WHERE user_id = 'a0000000-0000-4000-8000-000000000003'::uuid OR LOWER(email) = 'theyareop@gmail.com';

DELETE FROM student_skill_progress WHERE user_id = 'a0000000-0000-4000-8000-000000000003'::uuid;

INSERT INTO student_skill_progress (
    user_id, skill_id, skill_name, category, base_percentage, diagnostic_score,
    lecture_score, marathon_score, total_score, latest_exam_score, status, verified, lectures_completed,
    current_milestone, next_milestone
) VALUES
