('a0000000-0000-4000-8000-000000000003'::uuid, 'mech_fea', 'FEA Stress Analysis (ANSYS)', 'Simulation', 40, 34, 15, 3, 92, 100.0, 'LIVE VERIFIED', TRUE, 15, 'Static structural mesh convergence', 'Non-linear plasticity & fatigue lifecycle'),
('a0000000-0000-4000-8000-000000000003'::uuid, 'mech_cfd', 'CFD Fluid & Thermal Flow', 'Simulation', 38, 34, 15, 3, 90, 100.0, 'LIVE VERIFIED', TRUE, 15, 'Boundary layer meshing & Navier-Stokes', 'Turbulence modeling (k-epsilon) & conjugate heat'),
('a0000000-0000-4000-8000-000000000003'::uuid, 'mech_mfg', 'CNC Machining & DFM Guidelines', 'Manufacturing', 40, 34, 15, 3, 92, 100.0, 'LIVE VERIFIED', TRUE, 15, 'G-Code generation & toolpath optimization', '5-Axis machining & automated CMM inspection'),
('a0000000-0000-4000-8000-000000000003'::uuid, 'mech_debug', 'Failure Analysis & Reliability', 'Quality Engineering', 40, 34, 15, 3, 92, 100.0, 'LIVE VERIFIED', TRUE, 15, 'Root-cause fractography & stress risers', 'Vibration FFT analysis & modal testing')
ON CONFLICT (user_id, skill_name) DO UPDATE
SET base_percentage = EXCLUDED.base_percentage,
    diagnostic_score = EXCLUDED.diagnostic_score,
    lecture_score = EXCLUDED.lecture_score,
    marathon_score = EXCLUDED.marathon_score,
    total_score = EXCLUDED.total_score,
    latest_exam_score = EXCLUDED.latest_exam_score,
    status = EXCLUDED.status,
    verified = EXCLUDED.verified,
    lectures_completed = EXCLUDED.lectures_completed;

UPDATE user_domain_progress
SET mastery_percent = 92.0,
    skill_scores = '{"SolidWorks & Parametric CAD": 94, "FEA Stress Analysis (ANSYS)": 92, "CFD Fluid & Thermal Flow": 90, "CNC Machining & DFM Guidelines": 92, "Failure Analysis & Reliability": 92}'::jsonb
WHERE LOWER(user_email) = 'theyareop@gmail.com';

